CREATE TABLE "article" ("id" text PRIMARY KEY NOT NULL, "slug" text NOT NULL UNIQUE, "published_title" text, "published_markdown" text, "published_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX "article_published_at_idx" ON "article" ("published_at");
CREATE TABLE "article_draft" ("id" text PRIMARY KEY NOT NULL, "article_id" text NOT NULL REFERENCES "article"("id") ON DELETE CASCADE, "title" text NOT NULL, "markdown" text NOT NULL, "updated_by" text NOT NULL REFERENCES "user"("id"), "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "article_draft_article_id_idx" ON "article_draft" ("article_id");
CREATE TABLE "jwks" ("id" text PRIMARY KEY NOT NULL, "public_key" text NOT NULL, "private_key" text NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL, "expires_at" timestamp);
CREATE TABLE "oauth_client" ("id" text PRIMARY KEY NOT NULL, "client_id" text NOT NULL UNIQUE, "client_secret" text, "client_discovery_id" text, "disabled" boolean DEFAULT false, "skip_consent" boolean DEFAULT false, "name" text, "icon" text, "metadata" jsonb, "redirect_uris" text[] NOT NULL, "post_logout_redirect_uris" text[], "token_endpoint_auth_method" text, "grant_types" text[], "response_types" text[], "scopes" text[], "contacts" text[], "client_id_issued_at" timestamp, "client_secret_expires_at" timestamp, "application_type" text, "subject_type" text, "sector_identifier_uri" text, "jwks" jsonb, "jwks_uri" text, "software_id" text, "software_version" text, "software_statement" text, "policy_uri" text, "terms_of_service_uri" text, "created_at" timestamp DEFAULT now() NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "oauth_resource" ("id" text PRIMARY KEY NOT NULL, "identifier" text NOT NULL UNIQUE, "name" text NOT NULL, "access_token_ttl" integer, "refresh_token_ttl" integer, "signing_algorithm" text, "scopes" text[], "audiences" text[], "metadata" jsonb, "disabled" boolean DEFAULT false, "created_at" timestamp DEFAULT now() NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "oauth_client_resource" ("id" text PRIMARY KEY NOT NULL, "client_id" text NOT NULL REFERENCES "oauth_client"("id") ON DELETE CASCADE, "resource_id" text NOT NULL REFERENCES "oauth_resource"("id") ON DELETE CASCADE, CONSTRAINT "oauth_client_resource_pair_idx" UNIQUE("client_id", "resource_id"));
CREATE TABLE "oauth_consent" ("id" text PRIMARY KEY NOT NULL, "client_id" text NOT NULL REFERENCES "oauth_client"("id") ON DELETE CASCADE, "user_id" text REFERENCES "user"("id") ON DELETE CASCADE, "reference_id" text, "resources" text[], "requested_user_info_claims" text[], "scopes" text[] NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "oauth_refresh_token" ("id" text PRIMARY KEY NOT NULL, "token" text NOT NULL UNIQUE, "client_id" text NOT NULL REFERENCES "oauth_client"("id") ON DELETE CASCADE, "session_id" text REFERENCES "session"("id") ON DELETE SET NULL, "user_id" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "reference_id" text, "authorization_code_id" text, "resources" text[], "requested_user_info_claims" text[], "scopes" text[] NOT NULL, "revoked" timestamp, "rotated_at" timestamp, "rotation_replay_response" text, "rotation_replay_expires_at" timestamp, "created_at" timestamp DEFAULT now() NOT NULL, "expires_at" timestamp NOT NULL);
CREATE TABLE "oauth_access_token" ("id" text PRIMARY KEY NOT NULL, "token" text NOT NULL UNIQUE, "client_id" text NOT NULL REFERENCES "oauth_client"("id") ON DELETE CASCADE, "session_id" text REFERENCES "session"("id") ON DELETE SET NULL, "user_id" text REFERENCES "user"("id") ON DELETE CASCADE, "reference_id" text, "authorization_code_id" text, "refresh_id" text REFERENCES "oauth_refresh_token"("id") ON DELETE SET NULL, "resources" text[], "requested_user_info_claims" text[], "scopes" text[] NOT NULL, "revoked" timestamp, "confirmation" jsonb, "created_at" timestamp DEFAULT now() NOT NULL, "expires_at" timestamp NOT NULL);
CREATE TABLE "oauth_client_assertion" ("id" text PRIMARY KEY NOT NULL, "expires_at" timestamp NOT NULL);
